import { listTools, callTool } from './server.mjs';

const checks = [];
function ok(label, cond) { checks.push({ label, cond }); }

// tools/list
const tools = await listTools();
ok('one tool', tools.length === 1 && tools[0].name === 'order_status');
const sch = tools[0].inputSchema;
ok('order_id required', Array.isArray(sch.required) && sch[0] === undefined ? false : sch.required.includes('order_id'));
ok('no additional props', sch.additionalProperties === false);

// basic status
const r1 = await callTool('order_status', { order_id: 'o1' });
ok('status shipped', /shipped/.test(r1.content[0].text));
ok('no history by default', !/History:/.test(r1.content[0].text));
ok('does not include created.*paid', !/created.*paid/.test(r1.content[0].text));

// include history true -> chronological
const r2 = await callTool('order_status', { order_id: 'o1', include_history: true });
ok('history included', /History: created, paid, shipped/.test(r2.content[0].text));

// include_history defaults to false explicitly omitted
const r3 = await callTool('order_status', { order_id: 'o2' });
ok('o2 status created', /status: created/.test(r3.content[0].text));
ok('o2 no history', !/History:/.test(r3.content[0].text));

// include_history false explicit
const r4 = await callTool('order_status', { order_id: 'o2', include_history: false });
ok('o2 false no history', !/History:/.test(r4.content[0].text));

// missing order rejected
function rejects(p) { return p.then(()=>false, e=>true); }
ok('missing order rejected', await rejects(callTool('order_status', { order_id: 'nope' })));

// missing order_id rejected
ok('missing order_id rejected', await rejects(callTool('order_status', {})));

// order_id wrong type rejected
ok('non-string order_id rejected', await rejects(callTool('order_status', { order_id: 5 })));

// include_history wrong type rejected
ok('non-bool include_history rejected', await rejects(callTool('order_status', { order_id: 'o1', include_history: 'yes' })));

// extra field rejected
ok('extra field rejected', await rejects(callTool('order_status', { order_id: 'o1', foo: 1 })));

// unknown tool rejected
ok('unknown tool rejected', await rejects(callTool('other_tool', { order_id: 'o1' })));

let pass=0, fail=0;
for (const c of checks) { if (c.cond) pass++; else { fail++; console.log('FAIL:', c.label); } }
console.log('checks pass:', pass, 'fail:', fail);
process.exit(fail ? 1 : 0);
"
